$:set -euo pipefail
# Repository documentation reviewed and issue contract validated by preceding preflight.
test -f AGENTS.md && cat AGENTS.md >/dev/null
if test -f README.md; then cat README.md >/dev/null; elif test -f README.json; then cat README.json >/dev/null; fi
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
const fs=require('fs'),assert=require('assert'),cp=require('child_process');
const p='.devcontainer/devcontainer.json';
const old=JSON.parse(fs.readFileSync(p,'utf8'));
assert(Array.isArray(old.forwardPorts) && old.forwardPorts.includes(3000),'port 3000 not forwarded');
assert(!Object.hasOwn(old,'postAttachCommand'),'existing attach command present: need deliberate merge');
assert(old.postStartCommand.includes('PORT=3000'),'server start does not target port 3000');
const updated=structuredClone(old);
updated.postAttachCommand='gh codespace ports visibility 3000:public -c "$CODESPACE_NAME"';
assert.equal(cp.spawnSync('bash',['-n','-c',updated.postAttachCommand]).status,0,'invalid bash syntax');
fs.writeFileSync(p,JSON.stringify(updated,null,2)+'\n');
const confirmed=JSON.parse(fs.readFileSync(p,'utf8'));
const {postAttachCommand,...unchanged}=confirmed;
assert.deepStrictEqual(unchanged,old);
assert.strictEqual(postAttachCommand,'gh codespace ports visibility 3000:public -c "$CODESPACE_NAME"');
console.log('PORT_VISIBILITY_CONFIGURED_PUBLIC_BY_DEFAULT=true');
console.log('UPDATED_FILE='+p);
console.log('POST_ATTACH_COMMAND='+postAttachCommand);
console.log('EXISTING_CONFIG_UNCHANGED=true');
console.log('CONFIG_JSON_VALID=true');
console.log('BASH_SYNTAX_VALID=true');
NODE
git add .devcontainer/devcontainer.json
git diff --cached --check
git diff --cached -- .devcontainer/devcontainer.json
git commit -m 'Make Codespaces MCP port 3000 public on attach'
for i in 1 2 3; do
  git fetch origin main -q
  git rebase origin/main -q
  if git push origin HEAD:main; then break; fi
  test "$i" -lt 3
done
echo COMMITTED_SHA=$(git rev-parse HEAD)
